// Protocol self-checks: round-trip decode of our own packets, and
// interop: decode a packet generated by the real fwknop CLI (skipped
// if the binary is not installed).

import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:crypto/crypto.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:fwknop/fko.dart';
import 'package:pointycastle/export.dart';

Uint8List _kiv(List<int> key, List<int> salt) {
  final out = BytesBuilder();
  var prev = const <int>[];
  while (out.length < 48) {
    prev = md5.convert([...prev, ...key, ...salt]).bytes;
    out.add(prev);
  }
  return out.toBytes();
}

/// Minimal inverse of buildSpaPacket, for verification only.
Map<String, String> decodePacket(String packet, Uint8List key,
    {Uint8List? hmacKey, Hash hmacHash = sha256}) {
  var msg = packet;
  if (hmacKey != null) {
    // stripped-b64 length of the digest
    final macLen = b64(Hmac(hmacHash, hmacKey).convert([0]).bytes).length;
    final macStr = packet.substring(packet.length - macLen);
    msg = packet.substring(0, packet.length - macLen);
    // HMAC covers the ciphertext b64 with the stripped salt prefix re-added.
    final want = b64(
        Hmac(hmacHash, hmacKey).convert(utf8.encode(b64RijndaelSalt + msg)).bytes);
    if (want != macStr) throw const FormatException('HMAC mismatch');
  }

  final raw = b64Decode(b64RijndaelSalt + msg);
  if (utf8.decode(raw.sublist(0, 8)) != 'Salted__') {
    throw const FormatException('missing Salted__ prefix');
  }
  final salt = raw.sublist(8, 16);
  final kiv = _kiv(key, salt);
  final cipher = PaddedBlockCipher('AES/CBC/PKCS7')
    ..init(
      false,
      PaddedBlockCipherParameters<CipherParameters, CipherParameters>(
        ParametersWithIV<KeyParameter>(
          KeyParameter(Uint8List.fromList(kiv.sublist(0, 32))),
          Uint8List.fromList(kiv.sublist(32, 48)),
        ),
        null,
      ),
    );
  final plain = utf8.decode(cipher.process(raw.sublist(16)));

  final digestPos = plain.lastIndexOf(':');
  final encoded = plain.substring(0, digestPos);
  final digest = plain.substring(digestPos + 1);
  if (digest != b64(sha256.convert(utf8.encode(encoded)).bytes)) {
    throw const FormatException('digest mismatch');
  }

  final f = encoded.split(':');
  final type = int.parse(f[4]);
  final hasNat = type == 2 || type == 4 || type == 6;
  final hasTimeout = type >= 3;
  return {
    'rand': f[0],
    'username': utf8.decode(b64Decode(f[1])),
    'timestamp': f[2],
    'version': f[3],
    'type': f[4],
    'message': utf8.decode(b64Decode(f[5])),
    if (hasNat) 'nat': utf8.decode(b64Decode(f[6])),
    if (hasTimeout) 'timeout': f.last,
  };
}

void main() {
  final key = decodeKey(base64Encode(utf8.encode('0123456789abcdef01234567')));
  final hmacKey = decodeKey(base64Encode(utf8.encode('abcdefghijklmnopqrstuvwxyz012345')));

  const hashes = {
    'md5': md5, 'sha1': sha1, 'sha256': sha256,
    'sha384': sha384, 'sha512': sha512,
  };

  test('round-trip: access + hmac + timeout (all digest types)', () {
    for (final entry in hashes.entries) {
      final packet = buildSpaPacket(
        sourceIp: '9.9.9.9',
        accessRequest: 'tcp/22',
        key: key,
        hmacKey: hmacKey,
        hmacDigest: entry.key,
        clientTimeout: 300,
        username: 'testuser',
      );
      expect(packet.contains('='), isFalse);
      final d = decodePacket(packet, key,
          hmacKey: hmacKey, hmacHash: entry.value);
      expect(d['username'], 'testuser');
      expect(d['version'], '3.0.0');
      expect(d['type'], '3'); // CLIENT_TIMEOUT_ACCESS_MSG
      expect(d['message'], '9.9.9.9,tcp/22');
      expect(d['timeout'], '300');
      expect(d['rand'], matches(RegExp(r'^\d{16}$')));
    }
  });

  test('round-trip: nat access, no hmac', () {
    final packet = buildSpaPacket(
      sourceIp: '9.9.9.9',
      accessRequest: 'tcp/8080',
      key: key,
      natAccess: '192.168.1.10,80',
    );
    final d = decodePacket(packet, key);
    expect(d['type'], '2'); // NAT_ACCESS_MSG
    expect(d['message'], '9.9.9.9,tcp/8080');
    expect(d['nat'], '192.168.1.10,80');
    expect(d['username'], '');
  });

  test('wrong hmac key is rejected', () {
    final packet = buildSpaPacket(
      sourceIp: '9.9.9.9',
      accessRequest: 'tcp/22',
      key: key,
      hmacKey: hmacKey,
    );
    expect(
      () => decodePacket(packet, key, hmacKey: key),
      throwsFormatException,
    );
  });

  const exe = '/usr/local/bin/fwknop';
  test('interop: decode a packet built by the real fwknop CLI', () {
    final keyB64 = base64Encode(utf8.encode('0123456789abcdef01234567'));
    final hmacB64 = base64Encode(utf8.encode('abcdefghijklmnopqrstuvwxyz012345'));
    for (final entry in hashes.entries) {
      final out = '${Directory.systemTemp.path}/fko_test.spa';
      final res = Process.runSync(exe, [
        '-A', 'tcp/22', '-a', '9.9.9.9', '-U', 'testuser', '-f', '300',
        '--key-base64-rijndael', keyB64, '--use-hmac', '--key-base64-hmac', hmacB64,
        '--hmac-digest-type', entry.key,
        '-D', '127.0.0.1', '-T', '-B', out, '--no-save-args', '--no-rc-file',
      ]);
      expect(res.exitCode, 0, reason: res.stderr.toString());

      final packet = File(out).readAsStringSync().trim();
      final d = decodePacket(packet, key,
          hmacKey: hmacKey, hmacHash: entry.value);
      expect(d['username'], 'testuser');
      expect(d['version'], '3.0.0');
      expect(d['type'], '3');
      expect(d['message'], '9.9.9.9,tcp/22');
      expect(d['timeout'], '300');
      File(out).deleteSync();
    }
  }, skip: File(exe).existsSync() ? null : 'fwknop CLI not found at $exe');
}
